const STEP_MAP = {
  '57d98384-2435-44ef-ac72-a6ce13ea8843': { step_title: 'Não Agendados / Meta',        categoria: 'Não Agendado', fase: 'Pré-agendamento' },
  '481c3384-26e5-4a9e-9235-eeccfd506ad5': { step_title: 'Não Agendados / Orgânico',     categoria: 'Não Agendado', fase: 'Pré-agendamento' },
  '096ecc8b-c84e-4f20-9df8-bc684c6dff45': { step_title: 'Agendados pela IA',            categoria: 'Agendado',     fase: 'Agendamento'     },
  '884ffe20-5cdb-4549-9301-07d38dc278a1': { step_title: 'Agendados pela CRC A',         categoria: 'Agendado',     fase: 'Agendamento'     },
  'c86979eb-cb1f-43b4-aabf-f726a304d011': { step_title: 'Agendados pela CRC B',         categoria: 'Agendado',     fase: 'Agendamento'     },
  'f79387f8-56fb-4d51-811c-4a06d3511ab8': { step_title: 'IA não conseguiu agendar',     categoria: 'Não Agendado', fase: 'Pré-agendamento' },
  'e98b1ea5-d5c7-4fb0-a7b2-9c639e4c5d05': { step_title: 'CRC não conseguiu agendar',   categoria: 'Não Agendado', fase: 'Pré-agendamento' },
  'f8747dd2-f9a8-4cf2-8205-35a7f1453dff': { step_title: 'Cliente Faltou',               categoria: 'Faltou',       fase: 'Pós-agendamento' },
  '1fbd8745-1aee-4721-8c53-1cdc534c3a87': { step_title: 'Cliente Compareceu',           categoria: 'Compareceu',   fase: 'Pós-agendamento' },
  '9e21a624-5287-4c56-8e18-1ccc31ee0f99': { step_title: 'Cliente Compareceu e Fechou',  categoria: 'Fechou',       fase: 'Fechamento'      },
};

const syncedAt = new Date().toISOString();
const result   = [];

for (const item of $input.all()) {
  const card = item.json;
  const step = STEP_MAP[card.stepId] || {
    step_title: card.stepTitle || '',
    categoria:  'outro',
    fase:       'desconhecido',
  };

  result.push({ json: {
    card_id:          card.id,
    card_key:         card.key          || '',
    step_id:          card.stepId       || '',
    step_title:       step.step_title,
    categoria:        step.categoria,
    fase:             step.fase,
    data_entrada:     (card.createdAt   || '').slice(0, 10),
    data_atualizacao: (card.updatedAt   || '').slice(0, 10),
    synced_at:        syncedAt,
  }});
}

return result;
